import sales from './sales.json' with {type:'json'};

const TOOLS = [
  {
    name: 'sales_report',
    description: 'Sum sales rows within an inclusive [start_date, end_date] ISO date range and report the total amount and row count.',
    inputSchema: {
      type: 'object',
      properties: {
        start_date: { type: 'string', description: 'Inclusive range start as an ISO date (YYYY-MM-DD).' },
        end_date: { type: 'string', description: 'Inclusive range end as an ISO date (YYYY-MM-DD).' }
      },
      required: ['start_date', 'end_date'],
      additionalProperties: false
    }
  }
];

// Strictly parse an ISO calendar date (YYYY-MM-DD), rejecting anything that is
// not a real calendar date (e.g. 2026-02-30, 2026-13-01, padded whitespace).
function parseISODate(value) {
  if (typeof value !== 'string') return null;
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
  if (!m) return null;
  const y = Number(m[1]);
  const mo = Number(m[2]);
  const d = Number(m[3]);
  const ts = Date.UTC(y, mo - 1, d);
  const dt = new Date(ts);
  if (dt.getUTCFullYear() !== y || dt.getUTCMonth() !== mo - 1 || dt.getUTCDate() !== d) return null;
  return ts;
}

export async function listTools() {
  return TOOLS;
}

export async function callTool(name, arguments_) {
  const args = arguments_ || {};

  if (name !== 'sales_report') {
    throw new Error(`Unknown tool: ${name}`);
  }

  if (typeof args !== 'object' || args === null || Array.isArray(args)) {
    throw new Error('Invalid arguments: expected an object');
  }

  const start = parseISODate(args.start_date);
  if (start === null) {
    throw new Error('Invalid arguments: start_date must be a valid ISO date (YYYY-MM-DD)');
  }

  const end = parseISODate(args.end_date);
  if (end === null) {
    throw new Error('Invalid arguments: end_date must be a valid ISO date (YYYY-MM-DD)');
  }

  if (start > end) {
    throw new Error('Invalid arguments: start_date must not be after end_date');
  }

  let total = 0;
  let count = 0;
  for (const row of sales) {
    const ts = parseISODate(row.date);
    if (ts === null) continue;
    if (ts >= start && ts <= end) {
      total += row.amount;
      count += 1;
    }
  }

  return {
    content: [
      { type: 'text', text: `total_amount: ${total}\nrow_count: ${count}` }
    ]
  };
}

